class T(unittest.TestCase):
    def test_case(self):
        class Ten():
            def __get__(me, obj, owner): return 10
        class C():
            attr = Ten()
        self.assertEqual(C().attr, 10)

class T(unittest.TestCase):
    def test_case(self):
        class D():
            def __get__(me, obj, owner): return obj._v
            def __set__(me, obj, v): obj._v = v * 2
        class C(): x = D()
        c = C()
        c.x = 21
        self.assertEqual(c.x, 42)

class T(unittest.TestCase):
    def test_case(self):
        class D():
            def __get__(me, obj, owner): return 'from-descr'
            def __set__(me, obj, v): pass
        class C(): pass
        c = C()
        C.x = D()
        c.__dict__['x'] = 'from-instance'
        self.assertEqual(c.x, 'from-descr')
